    // sets the .seq and .alt links for END nodes
    func resolveGrammarNodeLinks(parent: GrammarNode?, alternate: GrammarNode?, build: GrammarBuild) {
        number = build.nodeCounter
        build.nodeCounter += 1
        switch kind {
